using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Analytic.NativePeriod;

internal sealed class OriginalHalfBinomialComplementMonodromyDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native period and source continuation with fixed original normalization.",
        H("OriginalHalfBinomialComplementMonodromy"),
        Blocks(
            Describe.Lean(DescribeId.Create("complementdomain"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementDomain"),
                H("The complementary chart domain"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The complementary chart consists of r for which 1-r belongs to the normalized exponential chart domain."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("complementn"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementN"),
                H("The complementary numerator"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The literal numerator is iP(1-r), with its original scalar phase."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("complementy"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementY"),
                H("The complementary denominator"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The continued denominator is -i times the continued native numerator at 1-r."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("complementpath"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementPath"),
                H("The complementary path"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The path in the zero-centered disk is 1-gamma."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gamma1"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.gamma1"),
                H("The positive one loop"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("gamma1(t)=1-(1/2)exp(2 pi i t). Its complementary path is exactly gamma0, so the exponential lift has positive orientation."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("complementary-equations"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementary_equations"),
                H("The equation and Wronskian after complement"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("In every complementary chart both components are holomorphic, have differentiable derivatives, and solve the same native Picard-Fuchs equation. Their oriented Wronskian is -i/(pi r(1-r)). The parameter reversal contributes a minus sign to first derivatives; the fixed scalar transformation contributes the second sign needed to preserve the native Wronskian. There is no assumption that the continued denominator never vanishes."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("complementary-path-continuation"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementary_path_continuation"),
                H("Every full complementary path"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every continuous path in the disk norm(1-r)<1 avoiding r=1 and starting at b has the native exponential lift of its complementary path. The transformed denominator charts agree as germs along this path and initially equal the original P as a germ. The numerator iP(1-r) is single-valued on this complementary disk."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-one-monodromy"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.positive_one_monodromy"),
                H("The exact native A1 action"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The positive loop around one has the same positive exponential lift in s=1-r. Its initial denominator germ is P and its returned denominator germ is P(r)-2iP(1-r), while the numerator is unchanged. On the original ordered column (n,y) the exact matrix is A1=[[1,0],[-2,1]], including the original scalar phase."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("complementary-loop-monodromy"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementary_loop_monodromy"),
                H("All integer complementary loop actions"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every continuous based loop in the full punctured complementary disk, there is an integer endpoint displacement of its exponential lift. The initial denominator germ is the literal P; the returned denominator germ is P(r)-2kiP(1-r). The numerator remains iP(1-r). This is the exact ordered-column action A1 to the integer power k, including inverse winding."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("complementary-initial-germ"),
                DeclarationHandle.Create("D5/S3/Analytic/NativePeriod/OriginalHalfBinomialComplementMonodromy.complementary_initial_germ"),
                H("The exact initial phase on the full lens"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("At every complex r in the full lens, the complementary denominator chart based at Log(1-r) equals the original P as a germ near r. The complementary numerator is literally iP(1-r). The identity n0(s)=iP(1-s) supplies the full overlap matching, including the fixed scalar minus i in the denominator transformation."))), DescribeRole.Theorem))));
}
